        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Deconstructive Argumentation & Antinomies. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Deconstructive Argumentation & Antinomies\".",
        "examples": "[{\"en\":\"I use \\\"Antinomy\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Antinomy\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Paradox\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Paradox\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Contradiction\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Contradiction\\\" trong các ngữ cảnh đời thực.\"}]"
