        "examples": "[{\"en\":\"I do not forget to practice \\\"Antinomy\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Antinomy\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Paradox\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Paradox\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Contradiction\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Contradiction\\\".\"}]"
