        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Defending Scholarly Monographs & Dissertations. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Defending Scholarly Monographs & Dissertations\".",
        "examples": "[{\"en\":\"I use \\\"Dissertation\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Dissertation\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Monograph\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Monograph\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Defense\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Defense\\\" trong các ngữ cảnh đời thực.\"}]"
