        "examples": "[{\"en\":\"I do not forget to practice \\\"Dissertation\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Dissertation\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Monograph\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Monograph\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Defense\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Defense\\\".\"}]"
