        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Native Discourse Reflexes & Spontaneous Wit. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Native Discourse Reflexes & Spontaneous Wit\".",
        "examples": "[{\"en\":\"I use \\\"Wordplay\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Wordplay\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Spontaneous\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Spontaneous\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Witticism\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Witticism\\\" trong các ngữ cảnh đời thực.\"}]"
