        "examples": "[{\"en\":\"I do not forget to practice \\\"Wordplay\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Wordplay\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Spontaneous\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Spontaneous\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Witticism\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Witticism\\\".\"}]"
